import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"PIGLIN KING 第五巻 王家の物語","description":"","frontmatter":{"title":"PIGLIN KING 第五巻 王家の物語","outline":"deep"},"headers":[],"relativePath":"story/5-1.md","filePath":"story/5-1.md"}'),o={name:"story/5-1.md"};function i(h,p,l,n,s,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="第五巻-王家の物語" tabindex="-1">第五巻 王家の物語 <a class="header-anchor" href="#第五巻-王家の物語" aria-label="Permalink to &quot;第五巻 王家の物語&quot;">​</a></h2><hr><h1 id="第一章-再会" tabindex="-1">第一章 再会 <a class="header-anchor" href="#第一章-再会" aria-label="Permalink to &quot;第一章 再会&quot;">​</a></h1><p>王国歴十五年。</p><p>ネザーに春は来ない。</p><p>それでも、グロウベリーの蔓が一斉に花を開く時期があり、人々はいつからか、それを「春」と呼ぶようになっていた。</p><p>王都 GOLDEN BASTION。</p><p>王立図書館。</p><p>あの噴水広場での出会いから、季節のないネザーで、それでも確かに一年近い月日が流れていた。</p><p>王として、果たすべき公務は、年々重くなっていった。会議。視察。式典。書類。気付けば、「レックス」として街へ出る時間は、ずっと少なくなっていた。それでも、上着の内側にしまった、あの小さな押し花の栞だけは、いつも肌身離さず持っていた。</p><p>「うーん……。」</p><p>KING PIGLIN I。</p><p>Aurex Goldtuskは、本棚の前で腕を組んでいた。</p><p>「歴史書……。」</p><p>「古代文明……。」</p><p>「どこだったかな。」</p><p>久しぶりに訪れた図書館は、記憶よりも本棚が増えていた。棚と棚の間に差し込む光が、埃の粒子をきらきらと照らしていた。</p><p>すると。</p><p>「失礼します。」</p><p>隣から、優しい声が聞こえた。</p><p>「もしかして。」</p><p>「『古代ネザー文明史』ですか？」</p><p>「え？」</p><p>オーレックスが振り向く。</p><p>そこにいたのは。</p><p>茶色の髪。</p><p>白い帽子。</p><p>優しい瞳。</p><p>一年前と、何も変わらない――いや、わずかに大人びた、その姿。</p><p>「……リリア？」</p><p>少女も目を丸くした。</p><p>「レックスさん！」</p><p>二人は思わず笑った。あの夕暮れの噴水広場以来、止まっていた何かが、もう一度動き始めるような笑い方だった。</p><p>「久しぶり。」</p><p>「お久しぶりです。」</p><p>「元気だった？」</p><p>「はい！」</p><p>「レックスさんは？」</p><p>「うん。」</p><p>「元気。」</p><p>その「元気」という一言の裏に、王としての多忙な日々がぎゅっと押し込まれていることを、リリアは知らなかった。けれど、知らなくていい。今だけは、ただの「レックス」として、ここに立っていたかった。</p><p>二人は自然と笑顔になっていた。</p><hr><h1 id="第二章-本好き" tabindex="-1">第二章 本好き <a class="header-anchor" href="#第二章-本好き" aria-label="Permalink to &quot;第二章 本好き&quot;">​</a></h1><p>「あの。」</p><p>「よかったら。」</p><p>「一緒に探しますか？」</p><p>「いいの？」</p><p>「もちろんです。」</p><p>二人は並んで本棚を探し始めた。背の高い棚が並ぶ通路は、まるで小さな迷宮のようだった。けれど、迷宮を歩くことに、二人ともまったく不安を感じていなかった。</p><p>「この本、おすすめですよ。」</p><p>「へぇ。」</p><p>「面白そう。」</p><p>「この作者さん、好きなんです。」</p><p>「僕も。」</p><p>「え？」</p><p>「本当？」</p><p>「うん。」</p><p>「好き。」</p><p>「わぁ！」</p><p>リリアは嬉しそうに笑った。その笑顔は、噴水の水しぶきよりも、ずっと無邪気に弾けた。</p><p>本棚の隙間から差し込む光が、少しずつ角度を変えていった。それが、時間が流れている唯一の証だった。</p><p>朝の光は、白く澄んでいた。</p><p>昼の光は、本のページに、まっすぐ落ちていた。</p><p>夕方の光は、いつの間にか、橙色に染まっていた。</p><p>気が付けば。</p><p>昼になり。</p><p>夕方になり。</p><p>閉館時間になっていた。</p><p>「あっ！」</p><p>「もうこんな時間！」</p><p>「本当だ。」</p><p>「ごめん。」</p><p>「つい夢中になっちゃった。」</p><p>「私もです。」</p><p>二人は顔を見合わせて笑った。誰かと過ごす時間が、こんなに早く流れることを、オーレックスは久しく忘れていた。会議室で過ごす時間は、いつも、ひどく長く感じられたから。</p><hr><h1 id="第三章-お忍び" tabindex="-1">第三章 お忍び <a class="header-anchor" href="#第三章-お忍び" aria-label="Permalink to &quot;第三章 お忍び&quot;">​</a></h1><p>翌日。</p><p>「また会える？」</p><p>オーレックスが聞いた。</p><p>「はい！」</p><p>「ぜひ！」</p><p>それから。</p><p>二人は何度も会うようになった。</p><p>市場。</p><p>王立公園。</p><p>噴水広場。</p><p>図書館。</p><p>オーレックスは兵士「レックス」として。</p><p>リリアはいつものリリアとして。</p><p>平和な日々を過ごした。</p><p>市場では、果実を売る店先で、見たことのない実を二人で覗き込んだ。公園では、ベンチに並んで座り、互いの好きな本を朗読し合った。噴水広場では、出会った日のことを、何度も思い出すように、二人で笑った。図書館では、相変わらず時間を忘れた。</p><p>「このケーキ美味しい！」</p><p>「本当だ。」</p><p>「甘い。」</p><p>「レックスさん。」</p><p>「甘いもの好きなんですね。」</p><p>「結構。」</p><p>「ふふふ。」</p><p>「意外です。」</p><p>戦場で剣を振るう男が、実は人知れず甘いものに目を細める――そんな一面を知る人間は、世界に数えるほどしかいなかった。リリアは、その数少ない一人になっていった。</p><p>そんな時間が、オーレックスには何より大切だった。冠の重さも、会議の長さも、その時間の中では、不思議と軽くなった。</p><hr><h1 id="第四章-二人を見守る者たち" tabindex="-1">第四章 二人を見守る者たち <a class="header-anchor" href="#第四章-二人を見守る者たち" aria-label="Permalink to &quot;第四章 二人を見守る者たち&quot;">​</a></h1><p>王宮。</p><p>「おーい。」</p><p>スターリンは双眼鏡を覗いていた。バルコニーの欄干に身を乗り出し、まるで遠征の偵察でもしているような顔つきだった。</p><p>「今日も行ったぞ！」</p><p>「市場だ！」</p><p>「やめなよ。」</p><p>ピックバーグは呆れていた。</p><p>「君。」</p><p>「完全に近所のおじさんだよ。」</p><p>「いいじゃねぇか！」</p><p>「青春だぞ！」</p><p>「青春。」</p><p>「いい響きだ。」</p><p>ピックバーグは、紅茶を片手に、半分だけ呆れた目で、半分だけ温かい目で、双眼鏡を構えるスターリンを見ていた。誰よりも豪快なこの男が、誰よりも誰かの幸せを喜ぶ性分だということを、彼はよく知っていた。</p><p>すると。</p><p>オーレックスが帰ってきた。</p><p>「ただいま。」</p><p>「おっ。」</p><p>「どうだった？」</p><p>スターリンがニヤニヤする。</p><p>「何が？」</p><p>「何がじゃねぇ！」</p><p>「リリアちゃんだよ！」</p><p>「ぶっ！」</p><p>オーレックスは咳き込んだ。</p><p>「な、なんで知ってるの！？」</p><p>「顔。」</p><p>「真っ赤。」</p><p>ピックバーグが冷静に言う。</p><p>「君。」</p><p>「分かりやすすぎる。」</p><p>「うぅ……。」</p><p>オーレックスは顔を覆った。冠を被って戦場に立つ時よりも、よほど狼狽していた。</p><p>すると。</p><p>スターリンは豪快に笑った。</p><p>「はっはっは！」</p><p>「いいじゃねぇか！」</p><p>「恋する黄金王！」</p><p>「やめて！」</p><p>「それだけはやめて！」</p><p>三人の笑い声が王宮に響いた。古い石壁が、その笑い声を、何度も柔らかく跳ね返した。</p><hr><h1 id="第五章-また明日" tabindex="-1">第五章 また明日 <a class="header-anchor" href="#第五章-また明日" aria-label="Permalink to &quot;第五章 また明日&quot;">​</a></h1><p>夕暮れ。</p><p>噴水広場。</p><p>水面が、橙色の光を割れた鏡のように散らしていた。</p><p>「今日は楽しかったです。」</p><p>リリアは微笑んだ。</p><p>「僕も。」</p><p>「また明日？」</p><p>「はい！」</p><p>「また明日。」</p><p>少女は手を振り、夕焼けの中へ消えていった。後ろ姿が、噴水の光と夕日の光の両方を浴びて、ほんの少しだけ輝いて見えた。</p><p>その姿を見送りながら、オーレックスは自然と笑顔になっていた。</p><p>戦争もない。</p><p>敵もいない。</p><p>ただ、大切な人と笑い合える。</p><p>それだけで、こんなにも幸せになれる。</p><p>剣を抜いて得た平和の先に、こんな静かな喜びが待っていたとは、あの炎の夜には、想像もできなかった。</p><p>しかし。</p><p>彼はまだ知らなかった。</p><p>リリアが、すでに気付いていることを。</p><p>「レックスさん。」</p><p>帰り道。</p><p>リリアは小さく呟いた。夕焼けに染まった一本道を歩きながら、独り言のように。</p><p>「やっぱり……。」</p><p>「王様ですよね？」</p><p>その声は、誰にも届かなかった。けれど、確かに、何かが動き始めていた。</p><p>そして。</p><p>王国最大の秘密は、思わぬ形で明らかになろうとしていた。</p>',176)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
